    body: "桌上那杯温水还冒着一点点热气，不烫口。小猪把自己蜷成小小的一团，先给她焐着被角。小金毛把下巴搁在她膝盖上，尾巴轻轻扫过地面。她听见身边的呼吸声，觉得自己也被稳稳接住。风停的时候，房间里静得能听见时钟轻响。一小片安静落下来，把今天的烦心事挡在了外面。枕头被拍了两下，软乎乎地陷下去，刚好托住脖子。她关掉头顶的大灯，只留床头这一小盏。今天辛苦啦，剩下的交给明天慢慢来。"
