    body: "云跑得很慢，从窗外这头挪到那头，像在散步。小猪把下巴垫在她膝盖上，呼噜声渐渐匀了。小金毛把下巴搁在她膝盖上，尾巴轻轻扫过地面。一点小小的坚持被看见，心里就不那么空了。被子里暖得刚刚好，不闷也不凉。她把手腕转了转，僵了一天的筋终于松开。她把还没做完的事写在纸上，写完就合上本子。她听见自己的呼吸慢慢变长，肩膀也跟着往下沉。身边有呼吸、有温度，夜里就不空。"
