    body: "桌上的水杯还温着，杯壁留着一圈浅浅的雾。小猪把白天收到的小开心，在心里又回放了一遍。小金毛在门口听了听远处，没有异常就安心趴下。那些说不出口的累，被陪伴悄悄接走了一些。窗外的风停了一会儿，屋里显得格外静。她把还没做完的事写在纸上，写完就合上本子。她把手腕转了转，僵了一天的筋终于松开。她翻了个身，被子顺着姿势回到肩上，不用自己去拉。不必把一切想明白，先好好休息。"
