    body: "她坐进沙发里，靠垫正好接住往后靠的肩膀。小猪陪着她不说话，只是贴着待在一旁。小金毛在她脚边转了个圈，把尾巴收好才趴下。她终于允许自己停下来，不再盯着时间。指尖碰到杯壁，温温的，热度刚刚好。旁边的呼吸一起一伏，慢慢合上了同一个节奏。她把杯子里的最后一口水喝完，轻轻放回桌上。一小片安静落下来，把今天的烦心事挡在了外面。愿她今晚睡得沉一点，醒来又是轻轻的一天。"
