    body: "散步回来，空气里带着一点青草和晒过的味道。小猪慢慢帮她把松开的被角掖到肩膀下面。小金毛先去闻了闻她带回来的衣角（只是闻闻气味），再摇着尾巴回来。那些说不出口的累，被陪伴悄悄接走了一些。灯下的小灰尘慢慢飘着，像不急着落下。她把窗子推开一条缝，让屋里的闷气散出去。她把杯子里的最后一口水喝完，轻轻放回桌上。今天这点小开心，就好好收进口袋里。"
