    body: "屋里的绿植叶子垂着，也像是要准备休息了。小猪听见她叹气，就轻轻哼了一声，表示自己在。小金毛在她起身时跟着抬头，确认她没走远才趴回去。累的时候不用逞强，身边留着柔软的位置给她。灯下的小灰尘慢慢飘着，像不急着落下。她听见自己的呼吸慢慢变长，肩膀也跟着往下沉。她关掉头顶的大灯，只留床头这一小盏。想起白天某个小小的笑，嘴角也松了下来。有他们在，夜里就不会太冷清。"
