    body: "天彻底黑透了，远处的楼一盏盏亮起小窗。小猪打了个哈欠，又努力把眼睛睁开等她先睡。小金毛把地上的碎纸团追得满屋跑，最后自己先累趴下。那些说不出口的累，被陪伴悄悄接走了一些。水杯放在桌面上，发出很轻的一声，随后又安静。两个人互相让着一点位置，谁也不挤谁。她把靠垫拍松，垫在腰后，坐得更舒服。她把杯子里的最后一口水喝完，轻轻放回桌上。今晚不用赶去哪里，这样就很好。"
