    body: "月亮升到屋檐上方，把地板铺成一块浅浅的银白。小猪把桌面的小灯往她这边挪了挪，让光刚好照到她手边。小金毛把一只前爪伸过来，轻轻碰了碰她的鞋。她不用解释什么，身边的陪伴已经懂了。窗玻璃上凝着细细的水汽，柔柔地蒙着光。一小片安静落下来，把今天的烦心事挡在了外面。她把杯子里的最后一口水喝完，轻轻放回桌上。她听见自己的呼吸慢慢变长，肩膀也跟着往下沉。呼吸慢慢放松下来，整个人都轻快了一点。"
