    body: "窗外的灯一盏盏亮起来，屋里也把暖光打开。小猪把身子缩成一团，只留一对耳朵露在外面。小金毛听到夸奖立刻原地转半圈，尾巴摇成小风扇。她把手放在暖和的毛上，心里慢慢踏实。灯罩把光收成一团，桌面上只亮着一小片。伸个懒腰，把肩膀往上提一提再松开，整个人轻快不少。她把腿收上来，整个人缩进沙发里。她在沙发上换了个姿势，把腿盘起来靠着垫子。这一天到这里收尾，已经足够好了。"
