    body: "楼道里的灯一层层暗下去，自家门缝还漏着光。小猪悄悄把她手边的温水往暖处挪了挪，怕凉了。小金毛听见窗外有动静，抬头看了看，又安心地靠回来。小小的热闹凑在一起，就是实实在在的开心。地板被暖灯照得发亮，踩上去温温的。她在沙发上换了个姿势，把腿盘起来靠着垫子。她把窗子推开一条缝，让屋里的闷气散出去。她把杯子里的最后一口水喝完，轻轻放回桌上。愿她今晚睡得沉一点，醒来又是轻轻的一天。"
